1: using System;
2: using System.Collections.Generic;
3: 
4: namespace DemoApp.Orders
5: {
6:     // 订单服务：下单流程状态机 + 订单持久化
7:     public sealed class OrderService
8:     {
9:         private readonly List<Order> _orders = new();
10:         public const int MaxItemsPerOrder = 20;
11: 
12:         public enum OrderStatus { Draft, Submitted, Paid, Cancelled }
13: 
14:         public Order CreateOrder(string customerId)
15:         {
16:             var order = new Order { Id = Guid.NewGuid(), CustomerId = customerId, Status = OrderStatus.Draft, CreatedAt = DateTime.Now };
17:             _orders.Add(order);
18:             return order;
19:         }
20: 
21:         public bool SubmitOrder(Guid orderId)
22:         {
23:             var order = _orders.Find(o => o.Id == orderId);
24:             if (order == null || order.Status != OrderStatus.Draft) return false;
25:             order.Status = OrderStatus.Submitted;
26:             return true;
27:         }
28: 
29:         public bool CancelOrder(Guid orderId)
30:         {
31:             var order = _orders.Find(o => o.Id == orderId);
32:             if (order == null || order.Status == OrderStatus.Paid) return false;
33:             order.Status = OrderStatus.Cancelled;
34:             return true;
35:         }
36: 
37:         public List<Order> GetOrders(string customerId) => _orders.FindAll(o => o.CustomerId == customerId);
38:     }
39: 
40:     public class Order
41:     {
42:         public Guid Id { get; set; }
43:         public string CustomerId { get; set; } = "";
44:         public OrderService.OrderStatus Status { get; set; }
45:         public DateTime CreatedAt { get; set; }
46:     }
47: }
